  ('koowan', 'koowan', '', '', '', 'Wiener Gaunersprache', 'kobern', '[{"kategorie": "wörtlich", "text": "\"kobern\" (vom mittelhochdeutschen\"koberen\"=\"anwerben\")"}, {"kategorie": "Gaunersprache", "text": "\"Kundschaft ködern\", auf Kundenfang gehen, nach Freiern Ausschau halten, \"anschaffen gehen\""}]'::jsonb, 'Obsd aum Fensta koowasd oda auf da Schdrossn, mochd an groossn Untaschiid!'),
  ('aukoowan', 'aukoowan', '', '', '', 'Wiener Gaunersprache', 'ankobern', '[{"kategorie": "wörtlich", "text": "\"ankobern\" (vom mittelhochdeutschen\"koberen\"=\"anwerben\")"}, {"kategorie": "Gaunersprache", "text": "\"Kundschaft ködern\", \"Freier ankeilen\", nach Freiern Ausschau halten, \"anschaffen gehen\""}]'::jsonb, 'De Maadln sitzn in da Ausloog und koowan duachs Fenstaglaasl zoolungskräftige Freia au!'),
  ('kooscha', 'kooscha', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'koscher', '[{"kategorie": "wörtlich", "text": "\"koscher\" (von jiddisch \"koscher\"=\"einwandfrei\")"}, {"kategorie": "rel.", "text": "\"rituell rein\", \"zum Verzehr geeignet\", \"nach jüdischem Ritus unbefleckt\", \"nach den jüdischen Speisegesetzen [Kashrut] rein und daher zum Verzehr erlaubt\""}, {"kategorie": "fig.", "text": "grundanständig, ehrlich, kreuzbrav"}, {"kategorie": "fig.", "text": "fair, korrekt, sauber, legal"}]'::jsonb, 'Sogoa im Hääfn kriagsd jetztd kooschares Fleisch!'),
  ('krawaeu', 'Krawäu', 'der', '', '', 'Grundwortschatz Wienerisch', 'Krawall', '[{"kategorie": "wörtlich", "text": "\"Krawall\" (vom lateinischen \"charavallium\"=\"Katzenmusik\" bzw. \"Straßenlärm\")"}, {"kategorie": "allg.", "text": "Lärm, Wirbel, Krach, Getöse, Tumult, Radau, [[Bahöö]]"}, {"kategorie": "", "text": "Streit, Zoff, Stunk, Ärger, Unruhe, Randale"}, {"kategorie": "", "text": "Aufruhr, Aufhebens, Theater, Zirkus"}]'::jsonb, 'Waunn de zwaa zsaummkumma, gibds imma an Krawäu!'),
  ('groigal', 'Groigal', 'das', '', '', 'Grundwortschatz Wienerisch', 'Groikerl', '[{"kategorie": "wörtlich", "text": "\"Griebchen\" (Verkleinerungsform, dialektale Ableitung vom mittelhochdeutschen \"griebe\"=\"kleines Krüstchen\")"}, {"kategorie": "med.", "text": "\"getrockneter Augenausfluss\", Augenschleim, Schlafkörnchen, \"Sandmännchenrest\", \"Schlafsand\", [[Augenpatzerl]]"}]'::jsonb, ''),
  ('kuaraasch', 'Kuaraasch', 'die', '', '', 'Grundwortschatz Wienerisch', 'Courage', '[{"kategorie": "wörtlich", "text": "\"Courage\" (vom französischen \"courage\"=\"Mut\")"}, {"kategorie": "allg.", "text": "Mut, Kühnheit, Beherztheit, Tapferkeit, [[Schneid]]"}]'::jsonb, 'Host de Kuaraasch oda ned?'),
  ('kuaraaschiwossa', 'Kuaraaschiwossa', 'das', '', '', 'Echte Wiener Schmähperlen', 'Courage-Wasser', '[{"kategorie": "wörtlich", "text": "\"Mutwasser\" (Determinativkompositum aus \"Courage\"=\"Mut\" und \"Wasser\"=\"Feuerwasser\")"}, {"kategorie": "scherzhaft für", "text": "\"flüssige Courage\", \"Nervenschnaps\", Feuerwasser, \"Stamperl Mutmacher\""}]'::jsonb, 'Bevuara si zu seina Schwiigamuada traud, schdessda si imma easchd a poa Schluck Kuaraaschiwossa ind Figua!'),
  ('krood', 'Krood', 'die', '', '', 'Grundwortschatz Wienerisch', 'Krot', '[{"kategorie": "wörtlich", "text": "\"Kröte\" (vom mittelhochdeutschen \"krot\"=Kröte\")"}, {"kategorie": "zool.", "text": "Erdkröte (lateinischer Name: \"Bufo bufo\"), \"Unke\", \"Rotbauchunke (lateinischer Name: \"Bombina bombina\")"}, {"kategorie": "fig.", "text": "\"bittere Pille\", \"saurer Apfel\", \"bitteres Übel\""}, {"kategorie": "bezogen auf Personen", "text": "\"Kröte\" (\"gemeine, bösartige Person\"), Widerling, Fiesling, [[Bosniigl]], (bezogen auf das weibliche Geschlecht):  \"Kröte\", \"Schabracke\", [[Schaastrommä]], [[Klodackn]], [[Grammä]]"}]'::jsonb, 'Wia soong zu oim, wos a waazige Haud hod und wiara Frosch ausschaud, imma nua ''Krood'' - egal ob Eadkrood oda Unkn!'),
  ('kroodnblaeaetschn', 'Kroodnbläätschn', 'die', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Krötenplätschen', '[{"kategorie": "wörtlich", "text": "\"Krötenblatt\" (Determinativkompositum aus [[Krood]]=\"Kröte\" und [[Plätsche]]=\"großes, breites Blatt\")"}, {"kategorie": "bot.", "text": "Huflattich (frühblühende, gelbblühende Heilpflanze, deren Blätter hustenstillend wirken), (lateinischer Name): \"Tussilago farfara\""}]'::jsonb, ''),
  ('kroodnfeidl', 'Kroodnfeidl', 'der', '', '', 'Wiener Gaunersprache', 'Krötenfeitel', '[{"kategorie": "wörtlich", "text": "\"Krötenmesser\" (Determinativkompositum aus [[Krood]]=\"Kröte\" und [[Feitl]]=\"Messer\")"}, {"kategorie": "scherzhaft für", "text": "stumpfes Messer, \"Billigmesser\", \"Schrottmesser\", \"Drecksklinge\", \"Gulaschschwert\""}]'::jsonb, 'Wea mid so an Kroodnfeidl daheakummd, ghead damit eignhändich rasiad!'),
  ('michl', 'Michl', 'der', '', '', 'Grundwortschatz Wienerisch', 'Michl', '[{"kategorie": "wörtlich, Koseform für:", "text": "\"Michael\" (männlicher Vorname)"}, {"kategorie": "allg.", "text": "Kerl, Bursche, Typ"}]'::jsonb, ''),
  ('miislsucht', 'Miislsucht', 'die', '', '', 'Grundwortschatz Wienerisch', 'Mieselsucht', '[{"kategorie": "wörtlich", "text": "\"Mieselsucht\" (vom mittelhochdeutschen \"miselsuht\"=\"Fleckseuche\")"}, {"kategorie": "med., hist.", "text": "\"Fleckenkrankheit\", \"Ausschlagseuche\", \"Masern\", \"Fleckfieber\""}, {"kategorie": "fig., moderner Sprachgebrauch", "text": "\"krankhafte Miesmacherei\", \"zwanghafte Kritiksucht\", \"Miesgelauntheit\", \"Griesgrämigkeit\", [[Grant]]"}]'::jsonb, 'Wea Miislsucht hod, kriagd a hoochs Fiawa und an Ausschloog, dea de gaunze Haut vabrennd!'),
  ('miislsichdich', 'miislsichdich', '', '', '', 'Grundwortschatz Wienerisch', 'mieselsüchtig', '[{"kategorie": "wörtlich", "text": "\"mieselsüchtig\" (vom mittelhochdeutschen \"miselsuht\"=\"Aussatz\" bzw. \"Lepra\")"}, {"kategorie": "med., hist.", "text": "\"von der Fleckenkrankheit befallen\", \"an der Fleckenseuche erkrankt\", \"von der Ausschlagseuche heimgesucht\", \"masernkrank\""}, {"kategorie": "fig., moderner Sprachgebrauch", "text": "\"krankhaft schlecht gelaunt\", mies gelaunt, unleidlich, griesgrämig, übellaunig, [[grantig]]"}, {"kategorie": "med.", "text": "\"schlecht beisammen\", \"schlapp\", \"kränklich\", [[marod]]"}]'::jsonb, 'Da Bua is miislsichdich, sei gaunze Köapa brennd - und sei Haut schbaunnd und brichd in roode, grausliche Fleckn aus!'),
  ('dia', 'dia', '', '', '', 'Grundwortschatz Wienerisch', 'dir', '[{"kategorie": "wörtlich", "text": "\"dir\" (Personalpronomen 2. Person Singular Dativ  - betontes \"dir\" - im Gegensatz zu [[da1]] [=unbetontes \"dir\"])"}, {"kategorie": "allg.", "text": "\"dir\", \"dir allein\", \"ausschließlich dir\" (wird zur gezielten Hervorhebung verwendet"}]'::jsonb, 'Des Loob gebüad dia, ned eam!'),
  ('miafadl', 'Miafadl', 'das', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Mierfadel', '[{"kategorie": "wörtlich", "text": "\"Meerschweinchen\" (von \"Mier\"=\"Meer\" und \"Fadl\" = \"Ferkel\" bzw. \"Schweinchen)"}, {"kategorie": "zool.", "text": "Hausmeerschweinchen, Zwergmeerschweinchen, (lateinischer Name): \"Cavia porcellus\""}, {"kategorie": "fig., meist in Bezug auf Kinder", "text": "\"Dreckschweinchen\", \"Dreckspatz\", \"Schlammschweinchen\", \"Schlammbärchen\""}]'::jsonb, 'Waunn I a Viech warad, warad I a Miafadl - klaa, flauschich und vafressn!'),
  ('meazl', 'Meazl', 'der', '', '', 'Wiener Mechaniker-Slang', 'Merzl', '[{"kategorie": "wörttlich, Kurzform für", "text": "\"Mercedes\" (benannt nach Mercédès Adrienne Ramona Manuela Jellinek (1889–1929) - sie war die Tochter des österreichisch-ungarischen Geschäftsmanns Emil Jellinek, der ein großer Förderer und Vertreter der Daimler-Motoren-Gesellschaft (DMG) war und darauf bestand, dass die Renn- und Serienfahrzeuge unter dem Namen seiner Tochter „Mercedes“ verkauft werden. Bereits 1900 wurde ein Modell unter dem Namen „Mercedes 35 PS“ entwickelt – ein revolutionäres Fahrzeug für die Zeit. 1902 wurde „Mercedes“ offiziell als Markenname registriert. 1926 fusionierten Daimler und Benz zur Marke Mercedes-Benz – eine Kombination aus dem Vornamen „Mercedes“ und dem Nachnamen von Karl Benz)"}, {"kategorie": "Automarke", "text": "\"Mercedes Benz\" (weltbekannte deutsche Automarke, bekannt für Luxus, Qualität und Innovation)"}]'::jsonb, 'Jetzd foada an sauteirän Meazl - dea wüü woi oin zeing, dassas gschoffd hod!'),
  ('memmoeln', 'memmöln', '', '', '', 'Grundwortschatz Wienerisch', 'memmeln', '[{"kategorie": "wörtlich", "text": "\"memmeln\" (vom mittelhochdeutschen \"memmelen\"=\"an der Mutterbrust saugen\")"}, {"kategorie": "scherzhaft für", "text": "\"rumschmatzen\", \"laut kauen\" (so als würde man an der \"Memme\" [=\"Mutterbrust\"] saugen), mampfen, schmatzen, [[baumpfn]]"}]'::jsonb, 'Hea auf zum Memmöln - du klingsd joa wiara Kua beim Möökn!'),
  ('moeoedung', 'Möödung', 'die', '', '', 'Grundwortschatz Wienerisch', 'Meldung', '[{"kategorie": "wörtlich", "text": "\"Meldung\" (vom mittelhochdeutschen \"meldunge\"=\"Anzeige\")"}, {"kategorie": "allg.", "text": "Mitteilung, Nachricht, Stellungnahme"}, {"kategorie": "", "text": "Äußerung, Kommentar, witzige oder provozierende Aussage, Bemerkung"}]'::jsonb, 'Laut offiziella Möödung is da Zugvakea wiida freigeem!'),
  ('mentschara', 'Mentschara', 'der', '', '', 'Grundwortschatz Wienerisch', 'Mentscherer', '[{"kategorie": "wörtlich", "text": "\"Mann, der den Mentschern nachjagt\" (vom mittelhochdeutschen \"daʒ mentsche\"=\"unverheiratetes Fräulein\")"}, {"kategorie": "scherzhaft für", "text": "Schürzenjäger, Weiberheld, [[Futkarli]], [[Weiberer]], [[Rammelkater]], [[Wetzer]], [[Steiger]], [[Stempler]], [[Puderant]]"}]'::jsonb, 'A Mentschara is wiara Jaaga - rennd seina Beute nooch, bisas ealeegd hod!'),
  ('mentschal', 'Mentschal', 'das', '', '', 'Grundwortschatz Wienerisch', 'Mentscherl', '[{"kategorie": "wörtlich", "text": "\"Mädchen\" (Verkleinerungsform von [[das Mentsch]], vom mittelhochdeutschen \"daʒ mentsche\"=\"unverheiratetes Fräulein\")"}, {"kategorie": "allg.", "text": "liebes kleines Mädchen, \"Herzchen\", \"Prinzesschen\", \"Engelchen\""}, {"kategorie": "pejorativ", "text": "Mädchen, Göre, Flittchen, [[Flutscherl]], [[Schledern]], [[Sandhas]], [[Zäächal]]"}]'::jsonb, 'So a liabs Mentschal - gaunz de Mama!'),
  ('motschka', 'Motschka', 'der', '', '', 'Grundwortschatz Wienerisch', 'Matschker', '[{"kategorie": "wörtlich", "text": "\"breiige Masse\" (vom tschechischen \"močka\"=\"Matsch\")"}, {"kategorie": "scherzhaft für", "text": "\"schlechtes Essen\", \"Fraß\", \"Einheitsbrei\", \"Matsch\", [[Baaz]], [[Papp]]"}, {"kategorie": "", "text": "\"Pfeifenbrei\", \"Teerbrei\", \"Tabaksaft\", \"Tabakmatsch\" (Tabakrückstand in der Pfeife), auch \"Kautabak-Rest\""}, {"kategorie": "fig.", "text": "Unsinn, dümmliches Gerede, [[Schmonzes]], [[Schmarren]]"}, {"kategorie": "", "text": "Durcheinander, Wirrwarr, [[Kuddelmuddel]], [[Schlamassel]], [[Pallawatsch]]"}, {"kategorie": "scherzhaft für", "text": "Sperma, Samenflüssigkeit, Ejakulat,  [[Tschuri]], [[Eiercognac]], [[kalter]] Bauer, [[Blauwossa]], [[Beidlmurra]]"}]'::jsonb, 'Mei Oide kochd imma so an Motschka zsaumm - den kriagsd nua mit drei Bia owe!'),
  ('motschkarant', 'Motschkarant', 'der', '', '', 'Grundwortschatz Wienerisch', 'Matschkerant', '[{"kategorie": "wörtlich", "text": "\"Matschkerant\" (vom tschechischen \"močka\"=\"Matsch\", der beim Kauen von Tabak durch die immer gleichbleibenden Kieferbewegungen im Mund entsteht)"}, {"kategorie": "allg.", "text": "\"Tabakkauer\", \"Tabaknuckler\", \"Tabakzuzler\""}]'::jsonb, 'So a Motschkarant schdinkd äaga ois a Tschickvaasn!'),
  ('motschkara', 'Motschkara', 'der', '', '', 'Grundwortschatz Wienerisch', 'Matschkerer', '[{"kategorie": "wörtlich", "text": "\"Matschkerer\" (vom tschechischen \"močka\"=\"Matsch\", der beim Kauen von Tabak durch die immer gleichbleibenden Kieferbewegungen im Mund entsteht)"}, {"kategorie": "allg.", "text": "\"Tabakkauer\", \"Tabaknuckler\", \"Tabakzuzler\""}]'::jsonb, 'So a Motschkara schdinkd äaga ois a Tschickvaasn!'),
  ('masemattn', 'Masemattn', 'die', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Masematten', '[{"kategorie": "wörtlich", "text": "\"Masematte\" (vom jiddischen \"masseh-mattan\" = \"Geben und Nehmen\")"}, {"kategorie": "allg.", "text": "\"Hin und Her\", Schacherei, Dealerei"}, {"kategorie": "fig.", "text": "\"Hin und Her\", Umstände, Schwierigkeiten, Probleme, Schwierigkeiten"}, {"kategorie": "Gaunersprache", "text": "\"krumme Geschäfte\", \"dubiose Machenschaften\", \"Schiebereien\", \"Gaunereien\""}, {"kategorie": "Gaunersprache", "text": "Einbruch, Einbruckdiebstahl, [[Bruch]], [[Kralowaad]]"}, {"kategorie": "ling.", "text": "Soziolekt, Rotwelsch, Gaunersprache, Subkultur-Sprache"}]'::jsonb, 'So a Masemattn weeng a poa schdingade Euro - aafoch nua lächalich!'),
  ('maggi', 'Maggi', 'das', '', '', 'Wiener Küche & Gaumenfreuden', 'Maggi', '[{"kategorie": "wörtlich", "text": "\"Maggi\" (international bekannte Lebensmittelmarke, die für ihre Würzmittel, Suppen, Fertiggerichte und Kochhilfen steht. Ursprünglich wurde das Unternehmen 1884 von dem Schweizer Unternehmer Julius Maggi in Kemptthal [Kanton Zürich, Schweiz] gegründet. Sein Ziel war es, die Ernährung der arbeitenden Bevölkerung zu verbessern, indem er günstige, nahrhafte und schnell zuzubereitende Produkte entwickelte)"}, {"kategorie": "Kulinarik", "text": "\"Suppenwürze\" (flüssige, dunkelbraune, besonders für Suppen und Soßen verwendete Speisewürze)"}]'::jsonb, 'A Schuss Maggi - und sogoa de toode Kua im Suppntopf lochd wiida!'),
  ('marii', 'Marii', 'die', '', '', 'Grundwortschatz Wienerisch', 'Marie', '[{"kategorie": "wörtlich", "text": "\"Marie\" (Kurzform für: [[Mariatheresientaler]])"}, {"kategorie": "hist.", "text": "\"Mariatheresientaler\" (eine seit 1741 bis heute geprägte Silbermünze mit dem Konterfei von Kaiserin Maria Theresia), \"Theresientaler\", \"österreichischer Reichstaler\", \"Wiener Taler\""}, {"kategorie": "Gaunersprache", "text": "Geld, Kohle, Zaster, [[Moos]], [[Flieder]], [[Zwirn]], [[Penise]], [[Geaschdl]], [[Schotter]], [[Näädsch]]"}]'::jsonb, 'Reib hea de Marii!'),
  ('mariateresientoola', 'Mariateresientoola', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Mariatheresientaler', '[{"kategorie": "wörtlich", "text": "\"Mariatheresientaler\" (=eine seit 1741 bis heute geprägte Silbermünze mit dem Konterfei von Kaiserin Maria Theresia)"}, {"kategorie": "allg.", "text": "\"Theresientaler\", \"österreichischer Reichstaler\", \"Wiener Taler\""}]'::jsonb, ''),
  ('teresientoola', 'Teresientoola', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Theresientaler', '[{"kategorie": "wörtlich", "text": "\"Theresientaler\" (=eine seit 1741 bis heute geprägte Silbermünze mit dem Konterfei von Kaiserin Maria Theresia)"}, {"kategorie": "allg.", "text": "\"Mariatheresientaler\", \"österreichischer Reichstaler\", \"Wiener Taler\""}]'::jsonb, 'Da Teresientoola wiad seit 1741 gpräägd und is aane da bekaunntastn Süüwamünzn da Wööd!'),
  ('marueuen', 'Marüün', 'die', '', '', 'Grundwortschatz Wienerisch', 'Marille', '[{"kategorie": "wörtlich", "text": "\"Marille\" (vom italienischen \"armellino\"=\"Amarille\" [=die armenische Frucht])"}, {"kategorie": "bot.", "text": "Marille (lateinischer Name): \"Prunus armeniaca\", (Deutschland): \"Aprikose\""}, {"kategorie": "fig., scherzhaft für", "text": "Kopf, Hirn, [[Hirnkasten]], [[Oberstüberl]]"}]'::jsonb, 'De Wachaua Marüün güüd ois bsundas aromatisch!'),
  ('mamelaad', 'Mamelaad', 'die', '', '', 'Wiener Küche & Gaumenfreuden', 'Marmelade', '[{"kategorie": "wörtlich", "text": "\"Marmelade\" (vom französischen \"marmelade\"=\"Marmelade\")"}, {"kategorie": "Deutschland", "text": "\"Konfitüre\" (mit Zucker eingekochtes Fruchtmark), Fruchtaufstrich, \"Jam\""}]'::jsonb, 'Soog in Wean nii ''Konfitüre'' schdott ''Mamelaad'' - sunst fliagd da s''Kipfal glei um d''Uan!'),
  ('mamelaadinga', 'Mamelaadinga', 'der', '', '', 'Echte Wiener Schmähperlen', 'Marmeladinger', '[{"kategorie": "wörtlich", "text": "\"Marmeladefresser\" (in Anspielung darauf, dass die deutschen Soldaten im 1. Weltkrieg statt Butter und Schmalz nur Billigmarmelade als Brotaufstrich bekamen - vom französischen \"marmelade\"=\"Marmelade\")"}, {"kategorie": "scherzhaft für", "text": "Norddeutscher, Preuße, [[Piefke]], [[Piefkenääsa]], [[Margarinefresser]], [[Marmeladebruder]]"}]'::jsonb, 'Gestan im Kaffeehaus haum si zwa Mamelaadinga beschwead, dass kaan Füütakaffee gibd - kaunnst da des vuaschdöön?'),
  ('mamelaadebruada', 'Mamelaadebruada', 'der', '', '', 'Echte Wiener Schmähperlen', 'Marmeladebruder', '[{"kategorie": "wörtlich", "text": "\"Marmeladebruder\" (in Anspielung darauf, dass die deutschen Soldaten im 1. Weltkrieg statt Butter und Schmalz nur Billigmarmelade als Brotaufstrich bekamen)"}, {"kategorie": "scherzhaft für", "text": "Norddeutscher, Preuße, [[Piefke]], [[Piefkenääsa]], [[Margarinefresser]], [[Marmeladinger]]"}]'::jsonb, 'Dea Mamelaadebruada do drüüm glaubd wiakli, a ''Seidl'' is a veganes Fleisch!'),
  ('magarinefressa', 'Magarinefressa', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Margarinefresser', '[{"kategorie": "wörtlich", "text": "\"Margarinefresser\"  (in Anspielung darauf, dass die deutschen Soldaten im 1. Weltkrieg statt Butter und Schmalz nur Billigmargarine als Brotaufstrich bekamen)"}, {"kategorie": "hist., scherzhaft für", "text": "Norddeutscher, Preuße, [[Piefke]], [[Piefkenääsa]], [[Marmeladinger]], [[Marmeladebruder]]"}]'::jsonb, 'Magarinefressa haums zu de deitschn Soidoodn im easchdn Wöödkriag gsoogd, wäu mas mid billiga Magarin oogschbeisd hod - Schmoiz oda Butta wia bei uns hods bei deenan nii geem!'),
  ('marood', 'marood', '', '', '', 'Grundwortschatz Wienerisch', 'marod', '[{"kategorie": "wörtlich", "text": "\"kränklich\" (vom französischen \"marauder\"=\"plündernd herumziehen\" [Im Dreißigjährigen Krieg wurden marodierende (= plündernd herumziehende) Soldaten „Marodeure“ genannt. Hieraus entwickelte sich in der Soldatensprache das Adjektiv \"marod\", womit verwundete oder kranke Soldaten bezeichnet wurden, die nicht mehr kämpfen konnten)"}, {"kategorie": "allg., in Bezug auf Personen", "text": "krank, unpässlich, kraftlos, mitgenommen, schlecht beisammen, [[fußmarod]], [[hirnmarod]]"}, {"kategorie": "in Bezug auf Dinge", "text": "heruntergekommen, kränkelnd, angeschlagen, abgewirtschaftet, sanierungsbedürftig, baufällig"}]'::jsonb, 'I bin heid gaunz marood - I bleib liawa im Bett!'),
  ('marooni', 'marooni', '', '', '', 'Echte Wiener Schmähperlen', 'maroni', '[{"kategorie": "wörtlich", "text": "\"maroni\" (scherzhafte Ableitung von \"marod\"=\"angeschlagen\", mit verhüllender italienisierender Endung)"}, {"kategorie": "scherzhaft für", "text": "marode, kränklich, schlecht beisammen, unpässlich, krankheitsgeplagt, angeschlagen"}, {"kategorie": "", "text": "finanziell marode, pleite, bankrott, [[neger]], [[stier]]"}]'::jsonb, 'Dea schaud so marooni aus, ois hädns eam iwad Nochd im Kölla eigschbead!'),
  ('maroonibrooda', 'Maroonibrooda', 'der', '', '', 'Grundwortschatz Wienerisch', 'Maronibrater', '[{"kategorie": "wörtlich", "text": "\"Kastanienbrater\" (Determinativkompositum aus [[Maroni]]=\"Esskastanie\" und [[Brater]]=\"Röster\")"}, {"kategorie": "allg.", "text": "Maroniverkäufer, Straßenverkäufer mit Maroniofen (Wiener Straßenverkäufer, der im Winter auf transportablen eisernen Holzkohlenöfen, die vor einfachen Holzverschlägen stehen, Edelkastanien [à„Maroni\"] bzw. Erdäpfel [\"Kartoffeln\"] brät und an Passanten verkauft), [[Winterschwalbe]], [[Kestenbrater]]"}]'::jsonb, ''),
